    b.fecha_acceso AS fecha,
    b.accion,
    b.modulo,
    b.entidad,
    b.id_entidad,
    b.estado_anterior,
    b.estado_nuevo,
    b.resultado,
    b.ip_acceso,
    b.detalle,
    b.id_usuario,
    COALESCE((((e.nombre)::text || ' '::text) || (e.apellido)::text), (u.nombre_usuario)::text, (b.nombre_usuario_intento)::text, 'Usuario desconocido'::text) AS usuario
   FROM ((public.bitacora_acceso b
     LEFT JOIN public.usuario u ON ((u.id_usuario = b.id_usuario)))
     LEFT JOIN public.empleado e ON ((e.id_empleado = u.id_empleado)));


--
-- Name: v_recibido_oc; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_recibido_oc AS
 SELECT id_orden_compra,
    (
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM (public.recepcion_bodega rb
                 JOIN public.detalle_recepcion_bodega drb ON ((drb.id_recepcion = rb.id_recepcion)))
              WHERE ((rb.id_orden_compra = oc.id_orden_compra) AND ((rb.estado)::text = ANY ((ARRAY['Completa'::character varying, 'Parcial'::character varying, 'Con Novedades'::character varying])::text[])) AND (drb.cantidad_aceptada > 0)))) THEN monto_total
            ELSE (0)::numeric
        END)::numeric(12,2) AS monto_recibido
   FROM public.orden_compra oc;


--
-- Name: v_expediente; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_expediente AS
 SELECT r.id_requisicion,
    r.codigo_requisicion,
    r.id_dependencia,
    r.id_periodo,
    r.estado AS estado_solicitud,
    pc.fase AS fase_cotizacion,
    oc.id_orden_compra,
    oc.numero_orden,
    oc.id_proveedor,
    oc.estado AS estado_orden,
    oc.monto_total AS monto_orden,
    COALESCE(rc.monto_recibido, (0)::numeric) AS monto_recibido,
    COALESCE(fa.monto_facturado, (0)::numeric) AS monto_facturado,
    COALESCE(pa.monto_pagado, (0)::numeric) AS monto_pagado,
        CASE
            WHEN ((r.estado)::text = ANY ((ARRAY['Rechazada'::character varying, 'Cancelada'::character varying])::text[])) THEN r.estado
            WHEN ((oc.id_orden_compra IS NOT NULL) AND (COALESCE(pa.monto_pagado, (0)::numeric) >= oc.monto_total)) THEN 'Pagada'::character varying
            WHEN (COALESCE(fa.monto_facturado, (0)::numeric) > (0)::numeric) THEN 'Facturada'::character varying
            WHEN ((oc.estado)::text = 'Entregada'::text) THEN 'Recibida'::character varying
            WHEN (COALESCE(rc.monto_recibido, (0)::numeric) > (0)::numeric) THEN 'Entrega parcial'::character varying
            WHEN (oc.id_orden_compra IS NOT NULL) THEN 'Orden de compra'::character varying
            WHEN (pc.fase IS NOT NULL) THEN 'En cotización'::character varying
            ELSE r.estado
        END AS etapa
   FROM (((((public.requisicion r
     LEFT JOIN public.proceso_cotizacion pc ON ((pc.id_requisicion = r.id_requisicion)))
     LEFT JOIN public.orden_compra oc ON (((oc.id_requisicion = r.id_requisicion) AND ((oc.estado)::text <> 'Cancelada'::text))))
     LEFT JOIN public.v_recibido_oc rc ON ((rc.id_orden_compra = oc.id_orden_compra)))
     LEFT JOIN ( SELECT factura.id_orden_compra,
            sum(factura.monto_total) AS monto_facturado
           FROM public.factura
          WHERE ((factura.estado)::text <> 'Rechazada'::text)
          GROUP BY factura.id_orden_compra) fa ON ((fa.id_orden_compra = oc.id_orden_compra)))
     LEFT JOIN ( SELECT f.id_orden_compra,
            sum(op.monto) AS monto_pagado
           FROM (public.orden_pago op
             JOIN public.factura f ON ((f.id_factura = op.id_factura)))
          WHERE ((op.estado)::text = 'Pagada'::text)
          GROUP BY f.id_orden_compra) pa ON ((pa.id_orden_compra = oc.id_orden_compra)));


--
-- Name: v_factura_estado; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_factura_estado AS
 SELECT f.id_factura,
    f.id_proveedor,
    f.numero_factura,
    f.fecha_emision,
    f.monto_total,
    f.fecha_vencimiento,
    f.estado AS estado_factura,
    op.id_orden_pago,
    op.estado AS estado_pago,
        CASE
            WHEN (((op.estado)::text = 'Pagada'::text) AND op.pagado_atraso) THEN 'Pagado con atraso'::text
            WHEN ((op.estado)::text = 'Pagada'::text) THEN 'Pagado'::text
            WHEN ((f.estado)::text = 'Rechazada'::text) THEN 'Rechazada'::text
            WHEN (f.fecha_vencimiento < CURRENT_DATE) THEN 'Vencido'::text
            ELSE 'Pendiente'::text
        END AS estado_visible
   FROM (public.factura f
     LEFT JOIN public.orden_pago op ON (((op.id_factura = f.id_factura) AND ((op.estado)::text <> 'Anulada'::text))));


--
-- Name: v_presupuesto_dependencia; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_presupuesto_dependencia AS
 SELECT pd.id_dependencia,
    pd.id_periodo,
    pd.monto_asignado,
    (COALESCE(sum(
        CASE
            WHEN ((r.estado)::text = ANY ((ARRAY['Aprobada'::character varying, 'En Compra'::character varying])::text[])) THEN COALESCE(r.monto_adjudicado, r.monto_estimado)
            ELSE NULL::numeric
        END), (0)::numeric))::numeric(12,2) AS comprometido,
    (COALESCE(sum(pg.monto_pagado), (0)::numeric))::numeric(12,2) AS pagado,
    ((pd.monto_asignado - COALESCE(sum(
        CASE
            WHEN ((r.estado)::text = ANY ((ARRAY['Aprobada'::character varying, 'En Compra'::character varying])::text[])) THEN COALESCE(r.monto_adjudicado, r.monto_estimado)
            ELSE NULL::numeric
        END), (0)::numeric)))::numeric(12,2) AS disponible
   FROM ((public.presupuesto_dependencia pd
     LEFT JOIN public.requisicion r ON (((r.id_dependencia = pd.id_dependencia) AND (r.id_periodo = pd.id_periodo))))
     LEFT JOIN ( SELECT oc.id_requisicion,
            sum(op.monto) AS monto_pagado
           FROM ((public.orden_pago op
             JOIN public.factura f ON ((f.id_factura = op.id_factura)))
             JOIN public.orden_compra oc ON ((oc.id_orden_compra = f.id_orden_compra)))
          WHERE ((op.estado)::text = 'Pagada'::text)
          GROUP BY oc.id_requisicion) pg ON ((pg.id_requisicion = r.id_requisicion)))
  GROUP BY pd.id_dependencia, pd.id_periodo, pd.monto_asignado;


--
-- Name: vale_salida; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.vale_salida (
    id_vale_salida integer NOT NULL,
    id_dependencia integer NOT NULL,
    id_usuario_solicitante integer NOT NULL,
    id_usuario_autoriza integer,
    fecha_salida timestamp with time zone DEFAULT now() NOT NULL,
    justificacion text,
    estado character varying(20) DEFAULT 'Pendiente'::character varying NOT NULL,
    CONSTRAINT vale_salida_estado_check CHECK (((estado)::text = ANY ((ARRAY['Pendiente'::character varying, 'Autorizado'::character varying, 'Entregado'::character varying, 'Cancelado'::character varying])::text[])))
);


--
-- Name: vale_salida_id_vale_salida_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.vale_salida ALTER COLUMN id_vale_salida ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.vale_salida_id_vale_salida_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


